<?php require __DIR__.'/includes/functions.php';require __DIR__.'/includes/data.php';$slug=$_GET['slug']??'';$p=package_by_slug($slug);if(!$p){http_response_code(404);$p=['title'=>'Trip not found','summary'=>'The requested trip could not be found.','days'=>0,'type'=>'','location'=>'','category'=>'','itinerary'=>[]];}$pageMeta=meta($p['meta_title']??$p['title'],$p['meta_description']??$p['summary']);require __DIR__.'/includes/header.php';$overview=trim($p['overview']??'')?:$p['summary'];$incs=array_values(array_filter(array_map('trim',preg_split('/\r\n|\r|\n/',trim($p['inclusions']??'')))));$excs=array_values(array_filter(array_map('trim',preg_split('/\r\n|\r|\n/',trim($p['exclusions']??'')))));if(!$incs)$incs=['Services specifically confirmed in your final written quotation','Trip coordination by Tanzania Wildlife Epic','Applicable guiding and transport where stated in the confirmed itinerary'];if(!$excs)$excs=['International flights unless explicitly confirmed','Travel insurance','Personal expenses and optional activities not confirmed in writing'];?>
